    static List<Integer> descendingLambda(List<Integer> in) {
        List<Integer> l = new ArrayList<>(in);
        l.sort((a, b) -> Integer.compare(b, a));
        return l;
    }
    static String[] sortedNames(String[] in) {
        String[] a = in.clone();
        Arrays.sort(a);
        return a;
    }
    static List<String> byLength(List<String> in) {
        List<String> l = new ArrayList<>(in);
        l.sort(Comparator.comparing(String::length).thenComparing(Comparator.naturalOrder()));
        return l;
    }
    static List<String> longestFirst(List<String> in) {
        List<String> l = new ArrayList<>(in);
        l.sort(Comparator.comparingInt(String::length).reversed());
        return l;
    }
    static Integer[] descBoxed(int[] in) {
        Integer[] a = new Integer[in.length];
        for (int i = 0; i < in.length; i++) a[i] = in[i];
        Arrays.sort(a, Collections.reverseOrder());
        return a;
    }
    static int[] descPrim(int[] in) {
        int[] a = in.clone();
        Arrays.sort(a);
        for (int i = 0, j = a.length - 1; i < j; i++, j--) {
            int t = a[i]; a[i] = a[j]; a[j] = t;
        }
        return a;
    }

    static int bad = 0;
    static void check(Object got, Object exp) {
        String g = String.valueOf(got), e = String.valueOf(exp);
        if (!g.equals(e)) { bad++; System.out.println("FAIL: got " + g + " expected " + e); }
    }
    static void done() { if (bad == 0) System.out.println("PASS"); }

    public static void main(String[] args) {
        check(ascending(List.of(3, 1, 2)), "[1, 2, 3]");
        check(naturalOwn(List.of(3, 1, 2)), "[1, 2, 3]");
        check(descending(List.of(3, 1, 2)), "[3, 2, 1]");
        check(descendingLambda(List.of(3, 1, 2)), "[3, 2, 1]");
        check(Arrays.toString(sortedNames(new String[]{"bo", "al", "cy"})), "[al, bo, cy]");
        check(byLength(List.of("bb", "a", "ccc", "aa")), "[a, aa, bb, ccc]");
        check(longestFirst(List.of("bb", "a", "ccc", "dd")), "[ccc, bb, dd, a]");
        check(Arrays.toString(descBoxed(new int[]{2, 9, 4})), "[9, 4, 2]");
        check(Arrays.toString(descPrim(new int[]{2, 9, 4})), "[9, 4, 2]");
        done();
    }
}
